const $=selector=>document.querySelector(selector);
const names={leafy:'Leafy gall',normal:'Normal growth',crown:'Crown gall',other:'Something else',unclear:'Still unsure',unreviewed:'Needs a look',not_checked:'Not checked'};
let session,data,current,dirty=false,working=false,worker,workerRequest=0,replyRequestId=crypto.randomUUID();
const replyDrafts=new Map();
function status(message,error=false){$('#desk-status').textContent=message;$('#desk-status').classList.toggle('error',error);}
function node(tag,text,className){const element=document.createElement(tag);if(text!==undefined)element.textContent=text;if(className)element.className=className;return element;}
function date(value){return value?new Date(value).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'';}
async function api(path,body){const response=await fetch(path,{cache:'no-store',...(body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf},body:JSON.stringify(body)})});const result=await response.json();if(response.status===401){$('#desk').hidden=true;$('#login').hidden=false;}if(!response.ok)throw new Error(result.error || 'Could not finish. Refresh and try again.');return result;}
async function run(fn){if(working)return;working=true;document.querySelectorAll('#desk button,#desk input,#desk select,#desk textarea,#publishing button,#open-publishing,#logout').forEach(x=>x.disabled=true);try{await fn();}catch(error){status(error.message,true);}finally{working=false;document.querySelectorAll('#desk button,#desk input,#desk select,#desk textarea,#publishing button,#open-publishing,#logout').forEach(x=>x.disabled=false);updateControls();if(data)renderPublishing();}}
function ask(title,description,button='Confirm'){return new Promise(resolve=>{const dialog=$('#confirm-action');$('#confirm-title').textContent=title;$('#confirm-description').textContent=description;$('#confirm-yes').textContent=button;dialog.showModal();const finish=value=>{dialog.close();$('#confirm-yes').onclick=null;$('#confirm-no').onclick=null;dialog.oncancel=null;resolve(value);};$('#confirm-yes').onclick=()=>finish(true);$('#confirm-no').onclick=()=>finish(false);dialog.oncancel=event=>{event.preventDefault();finish(false);};});}
function filtered(){return (data?.items || []).filter(item=>{const filter=$('#queue-filter').value;return filter==='all' || (filter==='pending' && item.category==='unreviewed') || (filter==='reviewed' && item.category!=='unreviewed') || (filter==='approved' && item.approved);});}
function renderQueue(){const items=filtered(),list=$('#queue-list');list.replaceChildren();$('#queue-count').textContent=`(${items.length})`;if(!items.length){list.append(node('p','No photos in this view. Try another filter.','queue-empty'));return;}for(const item of items){const button=node('button',undefined,'queue-item');button.type='button';button.setAttribute('aria-current',String(item.id===current?.id));const image=node('img');image.src=`/api/admin/reviews/${item.id}/photo`;image.alt='';image.loading='lazy';const text=node('span');text.append(node('strong',names[item.category]),node('small',date(item.createdAt)),node('small',item.approved?`Approved ${item.role==='evaluation'?'check':'reference'}`:item.trainingAllowed?'Training permission granted':'Private review only'));button.append(image,text);button.addEventListener('click',()=>choose(item.id));list.append(button);}}
function updateControls(){if(!current)return;const eligible=current.trainingAllowed && ['leafy','normal','crown'].includes(current.category);$('#approve').disabled=working || dirty || !eligible || current.approved;$('#example-role').disabled=working || dirty || !eligible || current.approved;$('#exclude').hidden=!current.approved;$('#withdraw').hidden=!current.trainingAllowed;$('#send-reply').disabled=working || !session?.replyReady;$('#reply-availability').textContent=session?.replyReady?'You’ll see the reply here after it is sent.':'Sending from this desk is awaiting domain verification. You can still reply from your inbox.';$('#approval-status').textContent=!current.trainingAllowed?'Review only. This photo cannot be added to the checker.':current.approved?`Approved as ${current.role==='evaluation'?'a held-out check':'a matching reference'}. Included when you publish a checked update.`:eligible?'Ready for your approval. Features are generated on this device; the photo stays private.':current.category==='unreviewed'?'Save your own visual assessment first.':'This assessment stays out of matching references because it is uncertain or a different condition.';}
async function choose(id,force=false){if(working && !force)return;if(dirty && !force && !await ask('Leave this review?','Your unsaved label and notes will be discarded.','Discard changes'))return;if(current?.id!==id)$('.review-panel').scrollTop=0;if(current)replyDrafts.set(current.id,$('#reply-body').value);current=data.items.find(x=>x.id===id);dirty=false;renderQueue();$('#selected').hidden=!current;$('#empty-selection').hidden=Boolean(current);if(!current)return;history.replaceState(null,'',`#${current.id}`);$('#photo').src=`/api/admin/reviews/${current.id}/photo`;$('#full-photo').href=$('#photo').src;$('#submitted-date').textContent=date(current.createdAt);$('#visitor-notes').textContent=current.notes || 'No notes from the grower.';$('#model-guess').textContent=`Checker guess: ${names[current.modelCategory] || 'Not checked'}`;$('#permission-state').textContent=current.trainingAllowed?'Training permission: yes':'Training permission: no';$('#label-options').querySelectorAll('input').forEach(x=>x.checked=x.value===current.category);$('#review-notes').value=current.reviewNotes;$('#plant-group').value=current.group;$('#example-role').value=current.role;$('#reply-address').textContent=current.email;$('#mail-reply').href=`mailto:${encodeURIComponent(current.email)}?subject=${encodeURIComponent('Your dahlia photo review')}`;$('#reply-body').value=replyDrafts.get(current.id) || '';replyRequestId=crypto.randomUUID();const historyBox=$('#reply-history');historyBox.replaceChildren();for(const reply of current.replies || []){const item=node('div',undefined,'reply-item');item.append(node('small',`${reply.status==='sent'?'Sent':'Waiting to send'} ${date(reply.sentAt || reply.createdAt)}`),node('p',reply.body));historyBox.append(item);}updateControls();}
async function refresh(keep=true){data=await api('/api/admin/reviews');renderQueue();const id=keep && current?.id || location.hash.slice(1);const target=data.items.find(x=>x.id===id) || filtered()[0];if(target){if(!filtered().some(x=>x.id===target.id))$('#queue-filter').value='all';await choose(target.id,true);}else{current=undefined;$('#selected').hidden=true;$('#empty-selection').hidden=false;}renderPublishing();}
function renderPublishing(){const prepared=data.prepared;$('#release-status').textContent=data.activeVersion?`Live version ${data.activeVersion.slice(0,8)}. ${data.items.filter(x=>x.approved).length} approved examples in the queue.`:'The original reference set is live.';$('#publish-references').hidden=!prepared?.report?.passed;const report=$('#check-report');report.replaceChildren();if(prepared){report.append(node('p',prepared.report.passed?'Checks passed. Review the results, then publish.':'Checks found additional wrong-category matches. Adjust the approved set before publishing.'));const table=node('table',undefined,'check-table'),head=node('tr');for(const text of ['Check','Match','Unsure','Wrong'])head.append(node('th',text));table.append(head);for(const [title,row]of [['Original',prepared.report.baseline],['Updated',prepared.report.regression],['Held out',prepared.report.heldOut]]){const tr=node('tr');for(const text of [title,row.match,row.abstain,row.wrong])tr.append(node('td',String(text)));table.append(tr);}report.append(table,node('p',`${prepared.referenceCount} community references; ${prepared.evaluationCount} held-out examples. Photos from one plant must share a group.`, 'fine'));}const releases=$('#release-history');releases.replaceChildren();for(const release of data.releases){if(!release.version)continue;const row=node('div',undefined,'release-item');row.append(node('span',`${date(release.publishedAt)} · ${release.version.slice(0,8)}`));const button=node('button',release.version===data.activeVersion?'Live':'Restore','text-button');button.disabled=release.version===data.activeVersion;button.addEventListener('click',()=>rollback(release.version));row.append(button);releases.append(row);}if(!data.releases.length)releases.append(node('p','No updates published yet.','fine'));}
$('#label-form').addEventListener('input',()=>{dirty=true;updateControls();});
$('#label-form').addEventListener('submit',event=>{event.preventDefault();if(!$('#label-form').reportValidity())return;const values=new FormData(event.target);run(async()=>{await api(`/api/admin/reviews/${current.id}`,{revision:data.revision,category:values.get('category'),notes:$('#review-notes').value,group:$('#plant-group').value});dirty=false;await refresh();status('Review saved.');});});
$('#refresh').addEventListener('click',()=>{if(dirty){status('Save your review before refreshing.',true);return;}run(async()=>{await refresh();status('Queue refreshed.');});});
$('#queue-filter').addEventListener('change',renderQueue);
function makeEmbedding(item){return new Promise(async(resolve,reject)=>{let url;try{const response=await fetch(`/api/admin/reviews/${item.id}/photo`,{cache:'no-store'});if(!response.ok)throw new Error('The private photo could not be loaded.');url=URL.createObjectURL(await response.blob());const image=new Image();image.src=url;await image.decode();const scale=Math.min(1,1536/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.round(image.naturalWidth*scale);canvas.height=Math.round(image.naturalHeight*scale);const context=canvas.getContext('2d',{willReadFrequently:true});context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);const pixels=context.getImageData(0,0,canvas.width,canvas.height).data.buffer;worker ||= new Worker('/vision-worker.js',{type:'module'});const id=++workerRequest;const timeout=setTimeout(()=>finish(new Error('Feature generation timed out. Try again.')),180000);const listener=event=>{if(event.data.type==='progress')status(event.data.text);else if(event.data.id===id && event.data.type==='embedding')finish(null,event.data);else if(event.data.id===id && event.data.type==='error')finish(new Error(event.data.message));};const failed=()=>finish(new Error('The on-device model could not run. Try a recent browser.'));function finish(error,value){clearTimeout(timeout);worker?.removeEventListener('message',listener);worker?.removeEventListener('error',failed);if(error){worker?.terminate();worker=undefined;reject(error);}else resolve(value);}worker.addEventListener('message',listener);worker.addEventListener('error',failed);worker.postMessage({type:'embed',id,width:canvas.width,height:canvas.height,pixels},[pixels]);}catch(error){reject(error);}finally{if(url)URL.revokeObjectURL(url);}});}
$('#approve').addEventListener('click',()=>run(async()=>{const selected=current,role=$('#example-role').value;status('Generating image features on this device…');const features=await makeEmbedding(selected);await api(`/api/admin/reviews/${selected.id}/approve`,{revision:data.revision,embedding:features.embedding,modelRevision:features.modelRevision,photoSha256:selected.photoSha256,role});await refresh();status('Example approved. Run the reference checks when you are ready to publish.');}));
$('#delete-photo').addEventListener('click',async()=>{if(working || !current)return;const id=current.id;if(!await ask('Permanently delete this photo?','This removes the stored photo, contact details, notes and reply history from this site. It also removes its approval for the checker. You cannot undo this. Already-sent emails and prior exports need separate removal.','Delete permanently'))return;run(async()=>{const result=await api(`/api/admin/reviews/${id}/delete`,{revision:data.revision,confirm:'delete-photo'});dirty=false;replyDrafts.delete(id);current=undefined;$('#selected').hidden=true;$('#photo').removeAttribute('src');history.replaceState(null,'','/admin');await refresh(false);status(result.status==='deleted'?'Photo deleted.': 'Photo removed from the desk. Storage deletion will retry automatically.');});});
$('#exclude').addEventListener('click',()=>run(async()=>{await api(`/api/admin/reviews/${current.id}/exclude`,{revision:data.revision});await refresh();status('Approval removed. The photo is excluded from the live checker.');}));
$('#withdraw').addEventListener('click',async()=>{if(!await ask('Withdraw training permission?','The photo will remain available for its private review, but will be excluded from the checker and future exports.','Withdraw permission'))return;run(async()=>{await api(`/api/admin/reviews/${current.id}/exclude`,{revision:data.revision,withdrawTraining:true});await refresh();status('Training permission withdrawn.');});});
const suggestions={leafy:'Thanks for sending your photo. The tightly clustered, distorted growth looks consistent with leafy gall. This is a visual assessment, not confirmation of an infection. Keep the plant apart and pause sharing tubers or cuttings while you seek advice from a plant diagnostic clinic.',normal:'Thanks for sending your photo. The visible shoots look consistent with normal growth. Keep watching how they develop. A normal-looking photo cannot rule out an infection; a plant diagnostic clinic can advise if the growth becomes unusual.',crown:'Thanks for sending your photo. The swelling looks consistent with crown gall. A photograph cannot confirm the cause. Avoid dividing or sharing this plant while you investigate, and contact a plant diagnostic clinic for advice.',other:'Thanks for sending your photo. The growth does not clearly fit our leafy gall or crown gall examples. Could you share another clear view of the crown and explain how the growth has changed?',unclear:'Thanks for sending your photo. I cannot confidently identify the growth from this view. Could you reply with another close-up of the crown in daylight, including the base of the shoots?'};
$('#suggest-reply').addEventListener('click',async()=>{if($('#reply-body').value.trim() && !await ask('Replace this draft?','Your current reply text will be replaced with suggested wording.','Replace draft'))return;$('#reply-body').value=suggestions[current.category] || suggestions.unclear;replyRequestId=crypto.randomUUID();});
$('#reply-body').addEventListener('input',()=>{replyRequestId=crypto.randomUUID();});
$('#send-reply').addEventListener('click',async()=>{const body=$('#reply-body').value.trim();if(body.length<10){status('Write a reply before sending.',true);return;}if(!await ask('Send this reply?',`This sends the text shown to ${current.email}. Suggested wording is editable and should match your own assessment.`,'Send reply'))return;run(async()=>{const result=await api(`/api/admin/reviews/${current.id}/reply`,{body,requestId:replyRequestId});replyDrafts.delete(current.id);$('#reply-body').value='';await refresh();status(result.status==='sent'?'Reply sent.':'Reply saved. Email delivery is pending and will retry automatically.');});});
$('#open-publishing').addEventListener('click',()=>{$('#publishing').showModal();renderPublishing();});$('#close-publishing').addEventListener('click',()=>$('#publishing').close());
$('#check-references').addEventListener('click',()=>run(async()=>{status('Checking approved examples…');await api('/api/admin/references/prepare',{});await refresh();status('Reference checks complete.');}));
$('#publish-references').addEventListener('click',async()=>{if(!await ask('Publish this reference update?','New inspections will use the checked examples. The model stays the same; private photos and contact details are not published.','Publish update'))return;run(async()=>{await api('/api/admin/references/publish',{version:data.prepared.version});await refresh();status('Reference update published. New inspections will use this version.');});});
async function rollback(version){if(!await ask('Restore this reference version?','New inspections will use this version. Any examples whose approval has changed must be reviewed again.','Restore version'))return;run(async()=>{await api('/api/admin/references/rollback',{version});await refresh();status('Reference version restored.');});}
$('#reset-references').addEventListener('click',()=>rollback(null));
$('#logout').addEventListener('click',()=>run(async()=>{await api('/auth/logout',{});location.href='/admin';}));
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
try{session=await api('/api/admin/session');if(!session.authenticated){$('#login').hidden=false;const review=location.hash.slice(1);if(/^[a-f0-9-]{36}$/.test(review))$('#signin').href=`/auth/github?review=${review}`;if(!session.enabled){$('#signin').hidden=true;$('#signin-detail').textContent='GitHub sign-in is awaiting server configuration.';}if(new URL(location.href).searchParams.has('signin'))status('Sign-in did not finish. Use the owner GitHub account and try again.',true);}else{$('#desk').hidden=false;$('#logout').hidden=false;$('#open-publishing').hidden=false;$('#account').textContent=session.login;await refresh();}}catch(error){status(error.message,true);}
